<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My orders | XenoPixels Shop</title><link rel="stylesheet" href="/assets/shop.css?v=2"><link rel="stylesheet" href="/assets/interactions.css"></head>
<body><?php require __DIR__ . '/topnav.php'; ?><main><section class="hero"><p class="eyebrow">ACCOUNT</p><h1>Your orders</h1></section><section class="grid"><?php foreach ($orders as $order): ?><article class="card card-body"><p class="eyebrow"><?= htmlspecialchars(strtoupper($order['status']), ENT_QUOTES, 'UTF-8') ?></p><h2><?= htmlspecialchars((string)($order['product_snapshot']['title'] ?? 'Shop order'), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></h2><p><?= htmlspecialchars($order['payment_method'], ENT_QUOTES, 'UTF-8') ?> · <?php if (in_array($order['payment_method'], ['mmoecon','zeni_cash'], true)): ?><?= number_format((int)$order['amount_minor']) ?><?php else: ?><?= number_format(((int)$order['amount_minor']) / 100, 2) ?><?php endif; ?> <?= htmlspecialchars($order['currency'], ENT_QUOTES, 'UTF-8') ?></p><small><?= htmlspecialchars($order['created_at'], ENT_QUOTES, 'UTF-8') ?></small></article><?php endforeach; ?><?php if (!$orders): ?><p class="empty">You do not have any orders yet.</p><?php endif; ?></section></main><script src="/assets/shop.js?v=0.1.1" defer></script></body></html>
